inline const CPixelShader& __fastcall CEnginePrimitiveRenderUtil::GetPixelShaderOutlineSmoothFillAlpha() { return NEngineInternal::GPPrimitiveRendererSharedData->PixelShaderOutlineSmoothFillAlpha; }
